  "items:ring_master_attack:name": "Anillo del Maestro de la Espada",
  "items:ring_master_completion:description": "Llevado solo por quienes han dominado las veintitrés disciplinas. Un aro silencioso de oro, concedido, jamás comprado.",
  "items:ring_master_hunting:name": "Anillo del Trampero",
  "items:ring_master_hunting:description": "Alisado por mil trampas colocadas y disparadas. Cada botín de una captura tiene un 5 % de probabilidad de caer por duplicado.",
  "items:ring_master_completion:name": "Anillo de la Culminación",
  "items:ring_master_cooking:description": "Manchado por cada plato que ha supervisado. Los platos preparados mientras se lleva puesto nunca fallan.",
  "items:ring_master_cooking:name": "Anillo del Cocinero de Almas",
  "items:ring_master_defence:name": "Anillo del Baluarte",
  "items:ring_master_farming:description": "Huele a tierra removida y estaciones pacientes. Los cultivos maduran un 8 % más rápido mientras se lleva puesto.",
  "items:ring_master_farming:name": "Anillo del Cuidatumbas",
  "items:ring_master_fishing:description": "Huele levemente a aguas profundas y cosas más antiguas. 5 % de probabilidad de conseguir una captura doble.",
  "items:ring_master_fishing:name": "Anillo del Pescador del Vacío",
  "items:ring_master_foraging:description": "Engastado con una esquirla de cada hoja que ha rozado alguna vez. 5 % de probabilidad de recolectar una cosecha doble.",
  "items:ring_master_foraging:name": "Anillo del Recolector Salvaje",
  "items:ring_master_herblore:description": "Reposado en vapores amargos más tiempo del que alcanza la memoria. Los tónicos y brebajes duran un 10 % más mientras se lleva puesto.",
  "items:ring_master_herblore:name": "Anillo del Maestro de Venenos",
  "items:ring_master_jewelcrafting:description": "Atrapa la luz como mil gemas sin engarzar. 5 % de probabilidad de tallar una gema doble.",
  "items:ring_master_jewelcrafting:name": "Anillo del Artesano de Gemas",
  "items:ring_master_leatherworking:description": "Tallado por un maestro que no desperdiciaba nada. 5 % de probabilidad de que el oficio ahorre sus materiales.",
  "items:ring_master_leatherworking:name": "Anillo del Maestro Curtidor",
  "items:ring_master_magic:name": "Anillo del Archimago",
  "items:ring_master_mining:description": "Forjado en las vetas más profundas, recuerda cada veta que ha tocado. 5 % de probabilidad de extraer mineral doble.",
  "items:ring_master_mining:name": "Anillo del Rompedor de Profundidades",
  "items:ring_master_power:name": "Anillo del Señor de la Guerra",
