  "quests:q_blackthorn_1:name": "Adentrarse en el Bosque de Espino Negro",
  "quests:q_blackthorn_2:description": "Adéntrate más en el Bosque de Espino Negro, hacia los túmulos bajo sus raíces, y derrota a 25 retoños nudosos.",
  "quests:q_blackthorn_2:name": "La espesura nudosa",
  "quests:q_boar_hunter:description": "Mata a 15 jabalíes salvajes en Los Pastos: sin cercas ni pastor, han adoptado costumbres propias, y el Baluarte de las Brasas necesita sus pieles.",
  "quests:q_boar_hunter:name": "La cacería salvaje",
  "quests:q_crypt_1:name": "Huesos de los caídos",
  "quests:q_crypt_2:name": "Muertos inquebrantables",
  "quests:q_crypt_3:name": "Silencio helado",
  "quests:q_dire_wolf_hunt:name": "El terror de las tierras salvajes",
  "quests:q_fighter_1:description": "Derrota a 75 enemigos en total. La sangre y el sudor forjan al luchador que el Baluarte de las Brasas necesita.",
  "quests:q_fighter_1:name": "Luchador curtido",
  "quests:q_fighter_2:description": "Abate a 200 enemigos en total. Los Siervos ya empiezan a recordar tu nombre.",
  "quests:q_fighter_2:name": "Guerrero endurecido",
  "quests:q_fighter_3:description": "Derrota a 500 enemigos en total. Cada enemigo caído es una entrada que la ceniza nunca se queda.",
  "quests:q_fighter_3:name": "Veterano de cien batallas",
