  "quests:q_gatherer:name": "Recolector",
  "quests:q_gatherer_2:description": "Recolecta 5.000 objetos en total para el Baluarte de las Brasas. Esta tierra solo entrega lo poco que le queda a quienes perseveran.",
  "quests:q_gatherer_2:name": "Coleccionista implacable",
  "quests:q_goblin_slayer:description": "Rechaza aún más a la banda goblin: mata a 30 goblins en las Tierras Fronterizas, que antaño fueron el muro escudo del Confín.",
  "quests:q_miner_1:description": "Alcanza el nivel 5 de Minería y abre vetas más ricas para la forja del Baluarte de las Brasas.",
  "quests:q_miner_1:name": "Pico y piedra",
  "quests:q_miner_2:description": "Alcanza el nivel 30 de Minería. Las vetas más profundas de las Tierras Fronterizas exigen un brazo más fuerte.",
  "quests:q_miner_2:name": "Voluntad de hierro",
  "quests:q_miner_3:description": "Alcanza el nivel 50 de Minería. Los minerales más raros del Confín yacen muy por debajo de la superficie, más hondo que nunca.",
  "quests:q_miner_3:name": "La llamada de las profundidades",
