  "quests:q_roc_fledgling:name": "Vigía de los cielos altos",
  "quests:q_shaman_hunt:description": "Los chamanes goblin sifonan Esencia Tenue de las viejas hogueras de guardia y agitan a la banda hacia la guerra. Silencia a 10 de ellos.",
  "quests:q_shaman_hunt:name": "Cacería de chamanes",
