  "campBuildings:camp_tavern:name": "La Taberna",
  "campBuildings:camp_tavern:description": "Halvard sirvió la primera ronda antes de que el techo estuviera terminado. Las noticias viajan más rápido sobre una jarra llena.",
  "items:black_market_crate_i:name": "Cajón del Mercado Negro I",
  "items:black_market_crate_i:description": "Un cajón que cambió de manos más de una vez antes de llegar a ti. Nadie pregunta qué hay dentro hasta que se abre.",
  "items:black_market_crate_ii:name": "Cajón del Mercado Negro II",
  "items:black_market_crate_ii:description": "Más pesado que el anterior, y los clavos son nuevos. Alguien quería que este pareciera normal.",
  "items:black_market_crate_iii:name": "Cajón del Mercado Negro III",
  "items:black_market_crate_iii:description": "Sellado con un timbre que significa algo en una ciudad que nunca has visitado.",
  "items:black_market_crate_iv:name": "Cajón del Mercado Negro IV",
  "items:black_market_crate_iv:description": "Traqueteó una vez de camino hasta aquí y no lo ha vuelto a hacer. Mejor ábrelo en algún lugar tranquilo.",
  "items:black_market_crate_v:name": "Cajón del Mercado Negro V",
  "items:black_market_crate_v:description": "El Forastero no quiso decir quién empacó este. Solo eso ya debería decirte algo.",
  "tavernGuests:halvard:role": "Tabernero",
  "tavernGuests:halvard:greeting": "Siéntate. Quien se sienta aquí, habla. Quien habla, se queda.",
  "tavernGuests:viktor:greeting": "Los buitres se envalentonan. Veinte cabezas, y pago.",
  "tavernGuests:billy:role": "Granjero",
  "tavernGuests:billy:greeting": "Mis parcelas están llenas y solo tengo dos manos.",
  "tavernGuests:grumm:role": "Minero",
  "tavernGuests:grumm:greeting": "El metal no miente. Cuarenta minerales, y hablamos.",
  "tavernGuests:brakka:role": "Leñadora",
  "tavernGuests:brakka:greeting": "Demasiado blando. Trae algo más duro.",
  "tavernGuests:nessa:role": "Pescadora",
  "tavernGuests:nessa:greeting": "La marea quita, la marea da. Hoy da. Aprovéchalo.",
  "tavernGuests:tamsin:role": "Recolectora",
  "tavernGuests:tamsin:greeting": "La vieja dice que debo aprender paciencia. Ayúdame a hacer trampa.",
  "tavernGuests:ilvara:role": "Herborista",
  "tavernGuests:ilvara:greeting": "El bosque recuerda recetas que todos habéis olvidado.",
  "tavernGuests:odo:role": "Cocinero",
  "tavernGuests:odo:greeting": "La guardia come carne cruda. Es una vergüenza. Ayúdame.",
  "tavernGuests:dashk:role": "Herrero",
  "tavernGuests:dashk:greeting": "Urga dice que el acero escucha a la paciencia. Yo no tengo. ¿Y tú?",
  "tavernGuests:merrit:role": "Armera",
  "tavernGuests:merrit:greeting": "Una hoja sin filo es un palo con excusas.",
  "tavernGuests:kell:role": "Curtidor",
  "tavernGuests:kell:greeting": "El buen cuero tiene una historia. Tráeme una.",
  "tavernGuests:sefra:role": "Joyera",
  "tavernGuests:sefra:greeting": "Una piedra lleva el clima consigo. Talla bien.",
  "tavernGuests:orin:role": "Creador de runas",
  "tavernGuests:orin:greeting": "El velo se rasga por arriba. Cóseme algo que aguante.",
  "tavernGuests:wenna:role": "Encantadora",
  "tavernGuests:wenna:greeting": "Los muertos no preguntan precios. Yo sí.",
  "tavernGuests:pim:role": "Ladrón",
  "tavernGuests:pim:greeting": "Nadie extraña lo que nunca contó.",
  "tavernGuests:torvald:role": "Constructor",
  "tavernGuests:torvald:greeting": "Una casa es una promesa hecha de madera. Tráeme madera.",
  "tavernGuests:stranger:role": "Mercado Negro",
  "tavernGuests:stranger:greeting": "No pregunto de dónde. Tú no preguntas hacia dónde.",
  "tavernGuests:ashka:role": "Comerciante caravanera",
  "tavernGuests:ashka:greeting": "Tres mercancías, buena mercancía, y no olvidaré tu nombre.",
  "tavernTasks:viktor_kill_zone:line": "Veinte cabezas bastarían para empezar. Despeja {count} en {zone}.",
  "tavernTasks:viktor_kill_tower:line": "La guardia de arriba también cuenta cabezas. Tráeme {count} de {zone}.",
  "tavernTasks:viktor_champion:line": "Uno de los nombrados anda cerca. Derríbalo y pago bien.",
  "tavernTasks:billy_deliver_harvest:line": "Mis parcelas están llenas. Tráeme {count} {target} de tus reservas.",
  "tavernTasks:billy_produce_harvest:line": "Recién cortado vale más. Cosecha {count} {target} para mí.",
  "tavernTasks:grumm_deliver_ore:line": "El metal no miente. Tráeme {count} {target}, y luego hablamos.",
  "tavernTasks:grumm_produce_ore:line": "Recién salido de la veta es lo mejor. Extrae {count} {target} fresco.",
  "tavernTasks:brakka_deliver_log:line": "Demasiado blando, la mayor parte de lo que recibo. Tráeme {count} {target}.",
  "tavernTasks:brakka_produce_log:line": "Tala {count} {target} tú mismo. Yo revisaré la veta.",
  "tavernTasks:nessa_deliver_fish:line": "La marea da hoy. Tráeme {count} {target} mientras lo hace.",
  "tavernTasks:nessa_produce_fish:line": "Lanza tu caña y saca {count} {target}, recién del agua.",
  "tavernTasks:tamsin_deliver_forage:line": "La vieja dice que debo aprender paciencia. Tráeme {count} {target} en su lugar.",
  "tavernTasks:tamsin_produce_forage:line": "Recolecta {count} {target} frescos. Fingiré que los encontré yo.",
  "tavernTasks:ilvara_deliver_potion:line": "El bosque recuerda lo que vosotros olvidasteis. Tráeme {count} {target}.",
  "tavernTasks:ilvara_produce_potion:line": "Prepara {count} {target} en el mortero. Las viejas recetas aún funcionan.",
  "tavernTasks:ilvara_produce_elixir:line": "Este necesita mano firme. Prepara {count} {target} sin derramar una gota.",
  "tavernTasks:odo_deliver_meal:line": "La guardia come carne cruda. Es una vergüenza. Tráeme {count} {target}.",
  "tavernTasks:odo_produce_meal:line": "Cocina {count} {target} en mi fogón. Cuidado con el fuego, muerde.",
  "tavernTasks:odo_produce_feast:line": "Un banquete de verdad, {count} {target}, nada quemado esta vez.",
  "tavernTasks:dashk_deliver_bar:line": "Urga cuenta cada lingote dos veces. Tráeme {count} {target}.",
  "tavernTasks:dashk_produce_bar:line": "Funde {count} {target} en la forja. Urga dice que el acero escucha a la paciencia.",
  "tavernTasks:dashk_produce_armor:line": "Forja {count} {target}. Quiero que Urga asienta, aunque sea una vez.",
  "tavernTasks:merrit_deliver_weapon:line": "Una hoja sin filo es un palo con excusas. Tráeme {count} {target}.",
  "tavernTasks:merrit_produce_weapon:line": "Forja {count} {target} y cuida el filo. Reviso cada una.",
  "tavernTasks:merrit_produce_weapon_next:line": "Ve más allá de tu propio nivel. Forja {count} {target}, un paso por delante.",
  "tavernTasks:kell_deliver_leather:line": "El buen cuero tiene una historia. Tráeme {count} {target}.",
  "tavernTasks:kell_produce_leather:line": "Curte {count} {target} para mí. Cúralo bien, o ni te molestes.",
  "tavernTasks:kell_produce_piece:line": "Cose {count} {target}. Quiero que dure más que quien lo lleve.",
