  "items:fiber_thornhemp:name": "Cáñamo espinoso",
  "items:fiber_thornhemp:description": "Fibra tosca de un seto que se defiende, lo bastante resistente para desviar el filo de una hoja.",
  "items:fiber_ghostsilk:name": "Seda fantasma",
  "items:fiber_ghostsilk:description": "Hebras pálidas hiladas por algo que vive donde la luz se agota.",
  "items:fiber_starflax:name": "Lino estelar",
  "items:fiber_starflax:description": "Fibra con un tenue brillo frío, como si recordara el cielo bajo el que creció.",
  "items:nettle_seed:name": "Semilla de ortiga",
  "items:nettle_seed:description": "Semilla negra y diminuta, plántala y cuida tus manos a la hora de la cosecha.",
  "items:flax_seed:name": "Semilla de lino",
  "items:flax_seed:description": "Semillita brillante y aceitosa de la que crece el tejido más antiguo del Reach.",
  "items:thornhemp_seed:name": "Semilla de cáñamo espinoso",
  "items:thornhemp_seed:description": "Semilla de cáscara dura de un seto que prefiere morder antes que florecer.",
  "items:ghostsilk_seed:name": "Semilla de seda fantasma",
  "items:ghostsilk_seed:description": "Semilla pálida como el hueso, dicen que brota mejor donde nada más quiere crecer.",
  "items:starflax_seed:name": "Semilla de lino estelar",
