  "dungeons:expunged_chapel:name": "La Capilla Expurgada",
  "dungeons:expunged_chapel:waveMeta.0.name": "La Procesión",
  "dungeons:expunged_chapel:waveMeta.1.name": "La Laguna",
  "dungeons:expunged_chapel:waveMeta.2.name": "El Expurgador",
  "quests:chronicle_22:name": "El Salón Vacío",
  "quests:chronicle_23:name": "La Consagración",
  "quests:chronicle_24:name": "Lo que bebieron los ídolos",
  "quests:chronicle_25:name": "Las Guirnaldas",
  "quests:chronicle_25:loreText": "Los vi fundir, en el Foso de Escoria, cuando aún creía que advertir era un oficio. Las primeras guirnaldas de hierro divino, guiadas por manos que no eran humanas. Aquí están de nuevo. Los Portadores de Guirnaldas avanzan en procesión por la larga sala, hombro con hombro, cargando lo que les pusieron encima como si la procesión aún no hubiera terminado. Nadie les dijo adónde van. Nunca estuvo decidido. Te cruzaste en su camino y cayeron como caen las obras: sin queja, con mucho estruendo. Estudié las rebabas de fundición en los fragmentos hasta que mi mano dejó de temblar. Las rebabas se quitan cuando una obra está terminada. Estas nunca se terminaron. Eso me alivia de un modo que prefiero no explicar.",
  "quests:chronicle_26:name": "Obras de asedio",
  "quests:chronicle_26:loreText": "Los ídolos eran sus obras de asedio contra el cielo. Anoté la frase cuando Drazhan la dijo, y solo hoy he entendido que lo decía literalmente. Al fondo del Salón se alzan en fila, inclinados hacia el cielo, con los brazos refundidos como brazos de lanzamiento, inacabados y sin amo. Lo que debían golpear sigue en silencio. Prefiero que nadie los termine. Los derribaste uno tras otro, y cuando cayó el último, el muro de detrás quedó libre. Una puerta que no figura en ningún plano del Salón, y yo tengo los planos. Tras ella, un ala en la que cada inscripción ha sido cincelada hasta borrarla, limpiamente, línea a línea. Alguien ha estado trabajando aquí. No creo que haya terminado.",
  "quests:chronicle_27:name": "El Expurgador",
  "quests:chronicle_27:description": "Limpia la Capilla Expurgada y abate al Expurgador: lo que recortó las escrituras sigue trabajando.",
  "quests:chronicle_27:loreText": "La procesión a la entrada, la laguna tras ella y, al fondo de la capilla, él. No levantó la vista cuando llegaste. Estaba cincelando. El Expurgador es la mano que cortó el nombre del Séptimo de las escrituras, y no dejó de cortar, porque un nombre puede volver si se le deja. Lo abatiste, y su obra quedó donde estaba: muros llenos de lagunas, todas con la misma forma. Recorrí una con la mano. Encaja con la laguna hacia la que rezan los sacerdotes. Lo escribo con sobriedad, porque no sé escribirlo de otro modo: el Séptimo no fue olvidado. Se le mantiene olvidado. Quién lo quiere así no figura en ningún libro que yo posea — todavía no. Las Guerras de los Dioses no empiezan con dioses. Empiezan con lo que alguien quiso expurgar.",
  "achievements:ach_chapter_22:name": "El Salón Vacío",
  "achievements:ach_chapter_22:description": "Termina el capítulo 22 de la Crónica: El Salón Vacío.",
  "achievements:ach_chapter_23:name": "La Consagración",
  "achievements:ach_chapter_23:description": "Termina el capítulo 23 de la Crónica: La Consagración.",
  "achievements:ach_chapter_24:name": "Lo que bebieron los ídolos",
  "achievements:ach_chapter_24:description": "Termina el capítulo 24 de la Crónica: Lo que bebieron los ídolos.",
  "achievements:ach_chapter_25:name": "Las Guirnaldas",
  "achievements:ach_chapter_25:description": "Termina el capítulo 25 de la Crónica: Las Guirnaldas.",
  "achievements:ach_chapter_26:name": "Obras de asedio",
  "achievements:ach_chapter_26:description": "Termina el capítulo 26 de la Crónica: Obras de asedio.",
  "achievements:ach_chapter_27:name": "Mantenido en el olvido",
  "achievements:ach_boss_the_expunger:name": "El corte termina",
